O2 = { (1,7),(1,8), (2,6),(2,7),(2,8),(2,9), (3,5),(3,6),(3,7),(3,8),(3,9),(3,10), (4,5),(4,6),(4,7),(4,8),(4,9),(4,10),(4,11), (5,4),*( (5,c) for c in range(6,13)), *( (6,c) for c in range(3,6)), *( (6,c) for c in range(7,14)), *( (7,c) for c in range(2,7)), *( (7,c) for c in range(8,15)), *( (8,c) for c in range(1,8)), *( (8,c) for c in range(9,16)), *( (9,c) for c in range(1,9)), *( (9,c) for c in range(10,14)), *( (10,c) for c in range(2,6)), *( (10,c) for c in range(7,13)), *( (11,c) for c in range(3,7)), *( (11,c) for c in range(8,12)), (12,4),(12,5),(12,9),(12,10) }
def components(bg_connect=4):
    rem={(r,c) for r in range(16) for c in range(16) if (r,c) not in D2}
    ds=[(-1,0),(1,0),(0,-1),(0,1)]
    if bg_connect==8: ds += [(-1,-1),(-1,1),(1,-1),(1,1)]
    comps=[]
    while rem:
      start=rem.pop(); q=[start]; comp={start}
      while q:
        r,c=q.pop()
